import  { useState, useEffect } from 'react';
import { distinctValues } from '@sassoftware/restafedit';
import BaseSelector from './BaseSelector';

function DistinctValues(props) {
  let { column, value, label, lib, table, where, style, onChange, designMode, _userProps,...eProps } = props;

  const [list, setList] = useState([]);
  const [sel, setSel] = useState(value);

  const _handleChange = (selx) => {
    setSel(selx);
    onChange(selx);
  };

  useEffect(() => {
    if (_userProps == null || _userProps.viyaEnv == null) {
      setList([]);
    } else {

      let appEnv = _userProps.viyaEnv
      if (column == null || column.trim().length === 0) {
        setList([])
      } else {
        
        let w = (where == null) ? '' : where;
        let t = {name: table};
        if (appEnv.source === 'cas') {
          t.caslib = lib;
        } else {
          t.libref = lib;
        }

        distinctValues(column, appEnv, t, w)
          .then(r => {
            
            setList(r[column]);
          })
          .catch(err => {
            
            console.log(err);
            setList([]);
            setSel('');
          })
        }
      }

  }, [label, column, lib,table, where, _userProps]);

  let pr = {
    name: 'distinct',
    value: sel,
    items: list,
    label: label,
    onChange: _handleChange,
    designMode: designMode, 
    style: style,
    eProps: eProps

  }
  
  return (
    <BaseSelector {...pr} />
  );
}

export default DistinctValues;
